svg.script:
document.SetBatteryStateOfCharge = function(percent, nom_capacity)
{
	var rect_max_alto = 63.0;

	var alto = (rect_max_alto/100.0)*(100-percent);

	document.getElementById("soc").innerHTML = String(percent);

	document.getElementById("nivel-bat").setAttribute("height", alto);

	energy = 48 * nom_capacity * percent / 100;
	document.getElementById("whbat").innerHTML = String(Math.round(energy));
}

document.Animation = function(Power, Current, VarExtra, bubble) 
{

	var text_id = "";
	var text_id2 = "";
	var luz_id 	= "";

	switch(bubble)
	{

	case "Bateria":

			document.getElementById("ibat").innerHTML = String(Math.abs(Current.toFixed(1)));
			document.getElementById("tempbat").innerHTML = String(Math.abs(VarExtra.toFixed(1)));
			break;

	case "Placa":

			document.getElementById("wplaca").innerHTML = String(Math.abs(Math.round(Power)));
			document.getElementById("iplaca").innerHTML = String(Math.abs(Current.toFixed(1)));
			document.getElementById("vplaca").innerHTML = String(Math.abs(VarExtra.toFixed(1)));
			break;

	case "Inversor":

			document.getElementById("winv").innerHTML = String(Math.abs(Math.round(Power)));
			document.getElementById("iinv").innerHTML = String(Math.abs(Current.toFixed(1)));
			break;

	case "Consumo":

			if (Power > 0) {
				light = 25*Power/1000;
				filament = "orange";
			} else {
				light = 0;
				filament = "#4d4d4d";
			}

			document.getElementById("wcons").innerHTML = String(Math.abs(Math.round(Power)));
			document.getElementById("luz-cons").setAttribute("r", light);
			document.getElementById("bombilla").style.stroke = filament;
			document.getElementById("filamento").style.stroke = filament;
			break;

	default:
			return;
	}


}
